{"file_text": "@using sv_7907851ae5e347b7a4d811b10c85c62f.Services

<div class="settings-section">
    <h2>Security</h2>

    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => _passwordExpanded = !_passwordExpanded">
            <span>Change Password</span>
            <span class="expand-icon">@(_passwordExpanded ? "▼" : "▶")</span>
        </button>
        @if (_passwordExpanded)
        {
            <div class="panel-body">
                <div class="form-group">
                    <label for="currentPwd">Current Password</label>
                    <input id="currentPwd" type="password" @bind="_currentPassword" class="form-control" />
                </div>
                <div class="form-group">
                    <label for="newPwd">New Password</label>
                    <input id="newPwd" type="password" @bind="_newPassword" class="form-control" />
                </div>
                <div class="form-group">
                    <label for="confirmPwd">Confirm Password</label>
                    <input id="confirmPwd" type="password" @bind="_confirmPassword" class="form-control" />
                </div>
                @if (!string.IsNullOrEmpty(_passwordError))
                {
                    <div class="error-message">@_passwordError</div>
                }
                @if (!string.IsNullOrEmpty(_passwordSuccess))
                {
                    <div class="toast-message success">@_passwordSuccess</div>
                }
                <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="security-item">
        <div class="toggle-group">
            <label class="toggle-label">
                <input type="checkbox" checked="@TwoFactorEnabled" disabled class="toggle-input" />
                <span class="toggle-switch"></span>
                <span>Two-Factor Authentication</span>
            </label>
            <span class="status-indicator @(TwoFactorEnabled ? "enabled" : "disabled")">
                @(TwoFactorEnabled ? "✓ Enabled" : "✗ Disabled")
            </span>
        </div>
        @if (Settings?.LastPasswordChange is not null)
        {
            <p class="info-text">Last password change: @Settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }
    </div>

    <!-- Active Sessions -->
    <h3>Active Sessions</h3>
    <div class="sessions-table">
        <table>
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th>Action</th>
                </tr>
            </thead>
            <tbody>
                @if (Settings?.Sessions is not null)
                {
                    @foreach (var session in Settings.Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@FormatLastActive(session.LastActive)</td>
                            <td>
                                @if (session.Id != CurrentSessionId)
                                {
                                    <button class="btn btn-danger btn-sm" @onclick="() => PromptRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="current-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                }
            </tbody>
        </table>
    </div>

    <!-- Revoke Confirmation Dialog -->
    @if (_sessionToRevoke is not null)
    {
        <div class="dialog-overlay">
            <div class="dialog">
                <h4>Revoke Session</h4>
                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in @_sessionToRevoke.Location?</p>
                <div class="dialog-actions">
                    <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke</button>
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public EventCallback<(string current, string newPwd)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool TwoFactorEnabled => Settings?.TwoFactorEnabled ?? false;
    private string CurrentSessionId => Settings?.Sessions.FirstOrDefault()?.Id ?? "";

    private bool _passwordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string _passwordError = "";
    private string _passwordSuccess = "";
    private ActiveSession? _sessionToRevoke;

    private async Task UpdatePassword()
    {
        _passwordError = "";
        _passwordSuccess = "";

        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "All fields are required.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New password and confirmation do not match.";
            return;
        }

        await OnChangePassword.InvokeAsync((_currentPassword, _newPassword));
        _passwordSuccess = "Password updated successfully!";
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
    }

    private void PromptRevoke(ActiveSession session) => _sessionToRevoke = session;
    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(_sessionToRevoke.Id);
            _sessionToRevoke = null;
        }
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.Now - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }
}
